<?php require_once __DIR__.'/../includes/bootstrap.php';require_admin();header('Content-Type: text/csv');header('Content-Disposition: attachment; filename="k2-admission-records.csv"');$out=fopen('php://output','w');fputcsv($out,['Student','Email','Course','Institution','Mode','Session','Status','Created']);$rows=$pdo->query("SELECT u.name,u.email,a.course,c.name college,a.mode,a.session,a.status,a.created_at FROM admissions a JOIN users u ON u.id=a.student_id LEFT JOIN colleges c ON c.id=a.college_id");foreach($rows as $r)fputcsv($out,$r);fclose($out);